#!/data/data/com.termux/files/usr/bin/bash
# ============================================================================
# Keep Android from killing Termux (phantom process killer, Doze, lmkd) - root or adb
# Generated by tpf from src/keepalive/ - do not edit, run ./tpf build.
# keepalive 2.0 (sources sha256:b35ea1aa34a996fe)
# ============================================================================
# shellcheck disable=SC2034  # available to the script, not always used
TPF_NAME=keepalive
TPF_VERSION=2.0
TPF_SOURCE_HASH=b35ea1aa34a996fe
# Keep Android from killing Termux (Android 12+), with root or without it.
#
#   termux-keepalive.sh setup    install adb and pair the device (once, no root)
#   termux-keepalive.sh on       turn the protection on
#   termux-keepalive.sh off      restore the original Android settings
#   termux-keepalive.sh status   show the current state
#
# What "on" does (with root or adb):
#   1. Disables the "phantom process killer" (Android 12+) that kills the child
#      processes of Termux (servers, Electron, builds). Same as "Disable child
#      process restrictions" in the developer options.
#   2. Sets the phantom process limit to the maximum and stops Android from
#      putting the default back (device_config sync disabled).
#   3. Adds Termux to the battery-saver (Doze) allowlist.
#   4. Allows Termux to run in the background (appops RUN_ANY_IN_BACKGROUND).
#   5. Takes a wake lock, and (root only) starts a guard that keeps
#      oom_score_adj below zero so lmkd, Android's memory killer, skips Termux.
#
# With root, "su" is used instead of adb: no pairing, no Wi-Fi. Without root,
# adb connects to the device itself through "Wireless debugging".
#
# Not handled here (do it by hand): vendor battery managers and "auto-start"
# lists have their own app killer; a reboot resets some settings, run "on" again.
#
# Environment: TERMUX_KEEPALIVE_MODE=root|adb forces the access mode.
set -u

# --- tpf: begin src/lib/core.sh ---
# Basics shared by every installer: checks, clean exit, signals, wake lock.
#
# Commands: have is_uint is_port require_termux require_aarch64
#           on_exit wake_lock
# --- tpf: begin src/lib/ui.sh ---
# Output style shared by every installer (see docs/STYLE.md).
#
#   [INFO] [ OK ] [ ?? ] [WARN]    six columns: the text always starts at column 8
#   [ERROR]                        danger: seven columns, written to stderr
#   [.   ] [..  ] [... ] ...       a task that is running (see task)
#
# Commands: info ok warn err detail step banner die
#           ask_yes_no ask_input ask_choice task
# Variable: TPF_ASSUME=yes|no answers every question without asking.

_UI_FRAMES=('[.   ]' '[..  ]' '[... ]' '[ ...]' '[  ..]' '[   .]')
_UI_CURSOR_HIDDEN=0
_TASK_PID=""

# ui_colors on|off|auto
ui_colors() {
    local mode="${1:-auto}"
    if [ "$mode" = auto ]; then
        if [ -t 1 ] && [ -z "${NO_COLOR:-}" ] && [ "${TERM:-}" != dumb ]; then mode=on; else mode=off; fi
    fi
    if [ "$mode" = on ]; then
        C_RESET=$'\033[0m'; C_BOLD=$'\033[1m'; C_DIM=$'\033[2m'
        C_INFO=$'\033[1;34m'; C_OK=$'\033[1;32m'; C_WARN=$'\033[1;33m'
        C_ERR=$'\033[1;31m'; C_ASK=$'\033[1;36m'
    else
        C_RESET=""; C_BOLD=""; C_DIM=""
        C_INFO=""; C_OK=""; C_WARN=""; C_ERR=""; C_ASK=""
    fi
}
ui_colors auto

# True when a running task can be animated in place.
_ui_animated() {
    [ -t 1 ] && [ "${TERM:-}" != dumb ] && [ -z "${TPF_NO_ANIM:-}" ]
}

# Everything printed is also appended, without colours, to $TPF_LOG_DIR/run.log.
_ui_log() {
    [ -n "${TPF_LOG_DIR:-}" ] && [ -d "${TPF_LOG_DIR}" ] || return 0
    printf '%s %-5s %s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$1" "$2" >>"$TPF_LOG_DIR/run.log" 2>/dev/null || true
}

_ui_line() {   # colour tag text
    printf '%s%s%s %s\n' "$1" "$2" "$C_RESET" "$3"
}

info() { _ui_line "$C_INFO" '[INFO]' "$*"; _ui_log INFO "$*"; }
ok()   { _ui_line "$C_OK" '[ OK ]' "$*"; _ui_log OK "$*"; }
warn() { _ui_line "$C_WARN" '[WARN]' "$*"; _ui_log WARN "$*"; }
err()  { _ui_line "$C_ERR" '[ERROR]' "$*" >&2; _ui_log ERROR "$*"; }

# A dimmed line aligned with the text of the lines above.
detail() { printf '       %s%s%s\n' "$C_DIM" "$*" "$C_RESET"; }

step() {
    printf '\n%s=== %s ===%s\n' "$C_INFO" "$*" "$C_RESET"
    _ui_log STEP "$*"
}

# banner TITLE [SUBTITLE]
banner() {
    local bar="============================================================"
    printf '\n%s%s\n %s\n' "$C_OK" "$bar" "$1"
    [ -z "${2:-}" ] || printf ' %s\n' "$2"
    printf '%s%s\n' "$bar" "$C_RESET"
}

die() {
    err "$*"
    if [ -n "${TPF_LOG_DIR:-}" ] && [ -d "${TPF_LOG_DIR}" ]; then
        printf '       %sLogs: %s%s\n' "$C_DIM" "$TPF_LOG_DIR" "$C_RESET" >&2
    fi
    exit 1
}

# ---------------------------------------------------------------------------
# Questions. They read /dev/tty, so they also work with `curl ... | bash`.
# The answer of ask_input / ask_choice is left in $ANSWER.
# ---------------------------------------------------------------------------
_ui_have_tty() { ( : </dev/tty ) 2>/dev/null; }

_ui_prompt() {   # text; reads one line from the terminal into $_UI_REPLY
    _UI_REPLY=""
    printf '%s[ ?? ]%s %s' "$C_ASK" "$C_RESET" "$1" >/dev/tty
    IFS= read -r _UI_REPLY </dev/tty || _UI_REPLY=""
}

# ask_yes_no "question" [yes|no]   -> status 0 for yes
ask_yes_no() {
    local question="$1" def="${2:-no}" hint
    case "${TPF_ASSUME:-}" in
        yes) _ui_line "$C_ASK" '[ ?? ]' "$question ${C_DIM}[auto: yes]${C_RESET}"; return 0 ;;
        no)  _ui_line "$C_ASK" '[ ?? ]' "$question ${C_DIM}[auto: no]${C_RESET}"; return 1 ;;
    esac
    if [ "$def" = yes ]; then hint="[Y/n]"; else hint="[y/N]"; fi
    if _ui_have_tty; then
        _ui_prompt "$question $hint "
        case "$_UI_REPLY" in
            y|Y|yes|Yes|YES|o|O|oui|Oui|OUI) return 0 ;;
            n|N|no|No|NO|non|Non|NON) return 1 ;;
            *) [ "$def" = yes ]; return ;;
        esac
    fi
    warn "No terminal available: default answer \"$def\" used ($question)"
    [ "$def" = yes ]
}

# ask_input "question" "default"   -> $ANSWER
ask_input() {
    local question="$1" def="${2:-}"
    ANSWER="$def"
    if [ -n "${TPF_ASSUME:-}" ]; then
        _ui_line "$C_ASK" '[ ?? ]' "$question ${C_DIM}[auto: ${def:-empty}]${C_RESET}"
        return 0
    fi
    if _ui_have_tty; then
        _ui_prompt "$question${def:+ [$def]} "
        [ -z "$_UI_REPLY" ] || ANSWER="$_UI_REPLY"
        return 0
    fi
    warn "No terminal available: default \"${def:-empty}\" used ($question)"
}

# ask_choice "question" DEFAULT option...   -> $ANSWER (one of the options)
ask_choice() {
    local question="$1" def="$2" opt n=0
    shift 2
    ANSWER="$def"
    if [ -n "${TPF_ASSUME:-}" ] || ! _ui_have_tty; then
        _ui_line "$C_ASK" '[ ?? ]' "$question ${C_DIM}[auto: $def]${C_RESET}"
        return 0
    fi
    _ui_line "$C_ASK" '[ ?? ]' "$question"
    for opt in "$@"; do
        n=$((n + 1))
        printf '       %s%d)%s %s%s\n' "$C_BOLD" "$n" "$C_RESET" "$opt" "$([ "$opt" = "$def" ] && printf ' (default)')"
    done
    _ui_prompt "Choice [1-$n or name] "
    n=0
    for opt in "$@"; do
        n=$((n + 1))
        if [ "$_UI_REPLY" = "$n" ] || [ "$_UI_REPLY" = "$opt" ]; then ANSWER="$opt"; return 0; fi
    done
    [ -z "$_UI_REPLY" ] || warn "\"$_UI_REPLY\" is not an option: default \"$def\" used"
}

# ---------------------------------------------------------------------------
# task "message" command [args...]
#
# Runs the command with its output sent to a log file and shows an animated
# [.   ] [..  ] [... ] marker while it runs, then replaces it by [ OK ] or
# [ERROR]. Returns the status of the command; on failure the last lines of the
# log are shown. The command runs in a subshell: variables it sets are lost.
# ---------------------------------------------------------------------------
_ui_cleanup() {
    if [ "$_UI_CURSOR_HIDDEN" = 1 ]; then printf '\033[?25h'; _UI_CURSOR_HIDDEN=0; fi
}

_task_logfile() {
    local slug
    slug="$(printf '%s' "$1" | tr -c 'A-Za-z0-9' '-' | tr -s '-' | sed 's/^-//; s/-$//' | cut -c1-48)"
    printf '%s/%s.log' "${TPF_LOG_DIR:-${TMPDIR:-/tmp}}" "${slug:-task}"
}

task() {
    local msg="$1" log rc=0 i=0 started=$SECONDS took=""
    shift
    [ -z "${TPF_LOG_DIR:-}" ] || mkdir -p "$TPF_LOG_DIR" 2>/dev/null || true
    log="$(_task_logfile "$msg")"
    if _ui_animated; then
        "$@" >"$log" 2>&1 </dev/null &
        _TASK_PID=$!
        printf '\033[?25l'; _UI_CURSOR_HIDDEN=1
        while kill -0 "$_TASK_PID" 2>/dev/null; do
            printf '\r\033[K%s%s%s %s' "$C_INFO" "${_UI_FRAMES[i % ${#_UI_FRAMES[@]}]}" "$C_RESET" "$msg"
            i=$((i + 1))
            sleep 0.15
        done
        wait "$_TASK_PID"; rc=$?
        _TASK_PID=""
        printf '\r\033[K'
        _ui_cleanup
    else
        _ui_line "$C_INFO" '[ .. ]' "$msg"
        "$@" >"$log" 2>&1 </dev/null; rc=$?
    fi
    [ $((SECONDS - started)) -lt 2 ] || took=" ${C_DIM}($((SECONDS - started))s)${C_RESET}"
    if [ "$rc" -eq 0 ]; then
        _ui_line "$C_OK" '[ OK ]' "$msg$took"
        _ui_log OK "$msg"
    else
        _ui_line "$C_ERR" '[ERROR]' "$msg (exit $rc)$took" >&2
        _ui_log ERROR "$msg (exit $rc)"
        if [ -s "$log" ]; then
            tail -n 8 "$log" | sed "s/^/       ${C_DIM}/; s/\$/${C_RESET}/" >&2
            printf '       %sFull log: %s%s\n' "$C_DIM" "$log" "$C_RESET" >&2
        fi
    fi
    return "$rc"
}
# --- tpf: end src/lib/ui.sh ---

have()    { command -v "$1" >/dev/null 2>&1; }
is_uint() { case "${1:-}" in '' | *[!0-9]*) return 1 ;; esac; }
is_port() { is_uint "${1:-}" && [ "$1" -ge 1 ] && [ "$1" -le 65535 ]; }

require_termux() {
    case "${PREFIX:-}" in
        *com.termux*) ;;
        *) die "This script must be run inside Termux." ;;
    esac
    [ -n "${HOME:-}" ] || die "\$HOME is not set."
}

require_aarch64() {
    case "$(uname -m)" in
        aarch64 | arm64) ;;
        *) die "Only 64-bit ARM (aarch64) is supported (this device: $(uname -m))." ;;
    esac
}

# ---------------------------------------------------------------------------
# Clean exit. Register cleanup commands with on_exit; they run in reverse
# order when the script ends, whatever the reason (end, die, Ctrl-C).
# ---------------------------------------------------------------------------
_TPF_EXIT_CMDS=()

on_exit() { _TPF_EXIT_CMDS+=("$1"); }

_tpf_exit() {
    local status=$? i
    trap - EXIT
    if [ -n "${_TASK_PID:-}" ]; then kill "$_TASK_PID" 2>/dev/null || true; fi
    _ui_cleanup
    for ((i = ${#_TPF_EXIT_CMDS[@]} - 1; i >= 0; i--)); do
        eval "${_TPF_EXIT_CMDS[i]}" || true
    done
    exit "$status"
}

_tpf_signal() {   # name status
    printf '\n' >&2
    err "Interrupted ($1)."
    exit "$2"
}

trap _tpf_exit EXIT
trap '_tpf_signal INT 130' INT
trap '_tpf_signal TERM 143' TERM

# wake_lock: keep Android from suspending Termux until the script ends.
_TPF_WAKE=0
wake_lock() {
    [ "$_TPF_WAKE" = 0 ] || return 0
    if have termux-wake-lock && termux-wake-lock >/dev/null 2>&1; then
        _TPF_WAKE=1
        on_exit 'termux-wake-unlock >/dev/null 2>&1'
    fi
    return 0
}
# --- tpf: end src/lib/core.sh ---
# --- tpf: begin src/lib/args.sh ---
# Command line options common to every installer.
#
#   -y, --yes   -n, --no   --no-color   --log-dir DIR   -V, --version   -h, --help
#
# In the option loop of a script:
#
#   while [ $# -gt 0 ]; do
#       case "$1" in
#           --my-option) MY=1 ;;
#           *) std_opt "$@" || die "Unknown option: $1 (try --help)"; shift "$STD_SHIFT"; continue ;;
#       esac
#       shift
#   done
#
# The script defines usage() and may print std_usage inside it.

STD_SHIFT=1
TPF_ASSUME="${TPF_ASSUME:-}"

# need_value OPTION ARGC   -> dies when an option that takes a value has none
need_value() {
    [ "$2" -ge 2 ] || die "Option $1 needs a value (try --help)"
}

std_usage() {
    cat <<'USAGE'
  -y, --yes        Answer "yes" to every question
  -n, --no         Answer "no" to every question
      --no-color   Plain output without colours
      --log-dir D  Write the logs to D
  -V, --version    Print the version and exit
  -h, --help       Show this help
USAGE
}

# std_opt "$@": handles the first argument if it is a common option.
# Returns 1 when it is not one. Sets STD_SHIFT to the number of arguments used.
std_opt() {
    STD_SHIFT=1
    case "$1" in
        -y | --yes) TPF_ASSUME=yes ;;
        -n | --no) TPF_ASSUME=no ;;
        --no-color) ui_colors off ;;
        --log-dir)
            need_value "$1" $#
            TPF_LOG_DIR="$2"
            STD_SHIFT=2
            ;;
        --log-dir=*) TPF_LOG_DIR="${1#*=}" ;;
        -V | --version)
            printf '%s %s\n' "$TPF_NAME" "$TPF_VERSION"
            exit 0
            ;;
        -h | --help)
            if declare -F usage >/dev/null; then usage; else printf 'Usage: %s [options]\n' "$TPF_NAME"; fi
            exit 0
            ;;
        *) return 1 ;;
    esac
}
# --- tpf: end src/lib/args.sh ---
# --- tpf: begin src/lib/log.sh ---
# Log directory of a script. Everything printed by info/ok/warn/err/step is also
# recorded (without colours) in $TPF_LOG_DIR/run.log; task output goes to one file
# per task in the same directory.
#
# Command: log_init [DIR]   (default: ~/.cache/tpf/$TPF_NAME, or --log-dir)

log_init() {
    TPF_LOG_DIR="${TPF_LOG_DIR:-${1:-$HOME/.cache/tpf/$TPF_NAME}}"
    mkdir -p "$TPF_LOG_DIR" 2>/dev/null || { warn "Cannot create the log directory $TPF_LOG_DIR"; TPF_LOG_DIR=""; return 0; }
    export TPF_LOG_DIR
}
# --- tpf: end src/lib/log.sh ---

PKG="com.termux"
STATE_DIR="$HOME/.cache/termux-keepalive"
STATE_FILE="$STATE_DIR/state"
MODE=""          # "root" (su) or "adb", chosen by ensure_access
OOM_TARGET=-300
GUARD_PID="$STATE_DIR/guard.pid"
GUARD_SH="$STATE_DIR/guard.sh"

SDK="$(getprop ro.build.version.sdk 2>/dev/null)"
is_uint "$SDK" || SDK=0

usage() {
    cat <<USAGE
Usage: ${0##*/} [options] setup|on|off|status

  setup    install adb and pair the device (once, no root)
  on       turn the protection on
  off      restore the original Android settings
  status   show the current state

Options:
USAGE
    std_usage
}

# ---------------------------------------------------------------------------
# Access to the Android shell: adb to the device itself, or root
# ---------------------------------------------------------------------------
adb_ready() {   # is a "device" (not offline/unauthorized) connected?
    have adb || return 1
    adb devices 2>/dev/null | awk 'NR>1 && $2=="device" {f=1} END {exit !f}'
}

adb_try_mdns() {   # finds the wireless-debugging port by itself
    local svc
    svc="$(adb mdns services 2>/dev/null | awk '/_adb-tls-connect/ {print $NF; exit}')"
    [ -z "$svc" ] || adb connect "$svc" >/dev/null 2>&1
    adb_ready
}

adb_connect() {
    have adb || { err "adb is not installed. Run first: $0 setup"; return 1; }
    adb start-server >/dev/null 2>&1
    adb_ready && return 0
    adb_try_mdns && return 0
    if [ -s "$STATE_DIR/last_endpoint" ]; then
        adb connect "$(cat "$STATE_DIR/last_endpoint")" >/dev/null 2>&1
        adb_ready && return 0
    fi
    warn "No adb connection. Is Wireless debugging on, with Wi-Fi connected?"
    detail "Developer options > Wireless debugging > note \"IP address & Port\"."
    ask_input "Address:port to connect to (empty to cancel)" ""
    [ -n "$ANSWER" ] || return 1
    adb connect "$ANSWER" 2>&1 | tail -n 1
    adb_ready || { err "Cannot connect."; return 1; }
    echo "$ANSWER" > "$STATE_DIR/last_endpoint"
}

root_available() {
    # Termux's own "su" is only a relay: require a real uid=0 answer.
    have su || return 1
    local out
    out="$(timeout 15 su -c id 2>/dev/null)" || return 1
    case "$out" in *"uid=0("*) return 0 ;; esac
    return 1
}

# Run a command in the Android shell (root or adb, depending on MODE).
sh_adb() {
    if [ "$MODE" = "root" ]; then su -c "$*" 2>&1; else adb shell "$@" 2>&1; fi
}

ensure_access() {
    case "${TERMUX_KEEPALIVE_MODE:-auto}" in
        adb) MODE="adb" ;;
        root)
            root_available || { err "Root requested but 'su' does not give uid=0."; return 1; }
            MODE="root"
            ;;
        *) if root_available; then MODE="root"; else MODE="adb"; fi ;;
    esac
    if [ "$MODE" = "root" ]; then
        ok "Root detected: using su (no adb needed)."
        return 0
    fi
    info "No root: using adb (wireless debugging)."
    adb_connect
}

# ---------------------------------------------------------------------------
# Root only: guard against lmkd.
# lmkd never kills a process whose oom_score_adj is NEGATIVE, but Android
# rewrites that value at every state change of the app. The guard puts it back
# every 3 seconds on all processes of Termux (Electron, code-server, builds...).
# -300 is deliberately less extreme than the system (-800/-900): if memory is
# really exhausted, the system stays first.
# ---------------------------------------------------------------------------
guard_running() {
    [ -s "$GUARD_PID" ] || return 1
    sh_adb "kill -0 $(cat "$GUARD_PID") 2>/dev/null && echo yes" | grep -q yes
}

guard_start() {
    [ "$MODE" = "root" ] || return 0
    local uid
    uid="$(id -u)"
    cat > "$GUARD_SH" <<GEOF
#!/system/bin/sh
# Written by termux-keepalive.sh - runs as root, only writes oom_score_adj.
UID_T=$uid; TARGET=$OOM_TARGET
while true; do
    for d in /proc/[0-9]*; do
        [ "\$(stat -c %u "\$d" 2>/dev/null)" = "\$UID_T" ] || continue
        cur="\$(cat "\$d/oom_score_adj" 2>/dev/null)"
        [ -n "\$cur" ] && [ "\$cur" -gt "\$TARGET" ] && echo "\$TARGET" > "\$d/oom_score_adj" 2>/dev/null
    done
    sleep 3
done
GEOF
    chmod 755 "$GUARD_SH"
    guard_stop quiet
    su -c "nohup sh $GUARD_SH >/dev/null 2>&1 & echo \$! > $GUARD_PID" >/dev/null 2>&1
    sleep 1
    if guard_running; then
        ok "lmkd guard running (oom_score_adj = $OOM_TARGET, pid $(cat "$GUARD_PID"))."
    else
        warn "The lmkd guard did not start."
    fi
}

guard_stop() {
    [ "$MODE" = "root" ] || return 0
    if [ -s "$GUARD_PID" ]; then
        sh_adb "kill $(cat "$GUARD_PID") 2>/dev/null" >/dev/null
        rm -f "$GUARD_PID"
        [ "${1:-}" = "quiet" ] || ok "lmkd guard stopped."
    fi
}

# ---------------------------------------------------------------------------
# setup
# ---------------------------------------------------------------------------
do_setup() {
    if [ "${TERMUX_KEEPALIVE_MODE:-auto}" != "adb" ] && root_available; then
        ok "Root available: no adb pairing needed. Run: $0 on"
        return 0
    fi
    task "Installing adb (android-tools)" pkg install -y android-tools || return 1
    cat <<'GUIDE'

Pairing (once):
  1. Settings > About > tap "Build number" 7 times (developer options).
  2. Developer options > turn on "Wireless debugging" (Wi-Fi connected).
  3. Tap "Wireless debugging" > "Pair device with pairing code".
     A window shows an ADDRESS:PORT and a 6-digit CODE.
     Tip: use a floating window or split screen for Termux, or the window
     closes when Termux comes back to the front.

GUIDE
    local pair code
    ask_input "PAIRING address:port (empty to skip)" ""
    pair="$ANSWER"
    if [ -n "$pair" ]; then
        ask_input "6-digit pairing code" ""
        code="$ANSWER"
        adb pair "$pair" "$code" || { err "Pairing failed."; return 1; }
        ok "Device paired."
    fi
    ask_input "CONNECTION address:port (main Wireless debugging screen, empty = automatic)" ""
    if [ -n "$ANSWER" ]; then
        adb connect "$ANSWER" && echo "$ANSWER" > "$STATE_DIR/last_endpoint"
    else
        adb_try_mdns
    fi
    if adb_ready; then
        ok "Connected. You can run: $0 on"
    else
        warn "Not connected yet. Run '$0 setup' or '$0 on' again (the port changes whenever Wi-Fi is toggled)."
    fi
}

# ---------------------------------------------------------------------------
# on / off
# ---------------------------------------------------------------------------
do_on() {
    [ "$SDK" -ge 31 ] || warn "Android < 12: there is no phantom process killer, only steps 3 to 5 apply."
    ensure_access || return 1

    info "Saving the current values..."
    {
        echo "monitor=$(sh_adb settings get global settings_enable_monitor_phantom_procs | tr -d '\r')"
        echo "maxphantom=$(sh_adb device_config get activity_manager max_phantom_processes | tr -d '\r')"
    } > "$STATE_FILE.new"
    # keep the original backup when "on" is run again
    [ -s "$STATE_FILE" ] || mv "$STATE_FILE.new" "$STATE_FILE"
    rm -f "$STATE_FILE.new"

    info "Disabling the phantom process killer..."
    sh_adb settings put global settings_enable_monitor_phantom_procs false >/dev/null
    sh_adb device_config set_sync_disabled_for_tests persistent >/dev/null
    sh_adb device_config put activity_manager max_phantom_processes 2147483647 >/dev/null

    info "Allowlisting Termux (battery saver and background)..."
    sh_adb cmd deviceidle whitelist +"$PKG" >/dev/null
    sh_adb cmd appops set "$PKG" RUN_ANY_IN_BACKGROUND allow >/dev/null
    sh_adb cmd appops set "$PKG" RUN_IN_BACKGROUND allow >/dev/null

    guard_start
    wake_lock
    ok "Protection on."
    do_status
    echo
    warn "Also to do by hand: Settings > Apps > Termux > Battery > \"Unrestricted\","
    warn "and allow auto-start / background in your vendor's battery manager."
}

do_off() {
    ensure_access || return 1
    local monitor="" maxp=""
    if [ -s "$STATE_FILE" ]; then
        monitor="$(sed -n 's/^monitor=//p' "$STATE_FILE")"
        maxp="$(sed -n 's/^maxphantom=//p' "$STATE_FILE")"
    fi

    info "Restoring the Android settings..."
    case "$monitor" in
        true | false) sh_adb settings put global settings_enable_monitor_phantom_procs "$monitor" >/dev/null ;;
        *) sh_adb settings delete global settings_enable_monitor_phantom_procs >/dev/null ;;
    esac
    sh_adb device_config set_sync_disabled_for_tests none >/dev/null
    case "$maxp" in
        '' | null) sh_adb device_config delete activity_manager max_phantom_processes >/dev/null ;;
        *) sh_adb device_config put activity_manager max_phantom_processes "$maxp" >/dev/null ;;
    esac
    sh_adb cmd deviceidle whitelist -"$PKG" >/dev/null
    sh_adb cmd appops set "$PKG" RUN_ANY_IN_BACKGROUND default >/dev/null
    sh_adb cmd appops set "$PKG" RUN_IN_BACKGROUND default >/dev/null
    guard_stop
    if have termux-wake-unlock; then termux-wake-unlock >/dev/null 2>&1; fi
    rm -f "$STATE_FILE"
    ok "Original settings restored. Android can kill Termux again."
    do_status
}

# ---------------------------------------------------------------------------
# status
# ---------------------------------------------------------------------------
status_line() { printf '%-34s : %s\n' "$1" "$2"; }

do_status() {
    step "State (Android $(getprop ro.build.version.release), SDK $SDK)"
    if [ -z "$MODE" ]; then
        if [ "${TERMUX_KEEPALIVE_MODE:-auto}" != "adb" ] && root_available; then MODE="root"
        elif adb_ready; then MODE="adb"; fi
    fi
    if [ -z "$MODE" ]; then
        warn "Neither root nor adb: the Android state cannot be read ($0 setup / on)."
        return 0
    fi
    local mon max wl bg
    mon="$(sh_adb settings get global settings_enable_monitor_phantom_procs | tr -d '\r')"
    max="$(sh_adb device_config get activity_manager max_phantom_processes | tr -d '\r')"
    wl="$(sh_adb cmd deviceidle whitelist | grep -c "$PKG")"
    bg="$(sh_adb cmd appops get "$PKG" RUN_ANY_IN_BACKGROUND | tr -d '\r' | head -n1)"
    status_line "Access mode" "$MODE"
    status_line "Phantom process killer (monitor)" "${mon:-?}   (false = disabled = protected)"
    status_line "Phantom process limit" "${max:-?}"
    status_line "Doze allowlist" "$([ "${wl:-0}" -ge 1 ] && echo yes || echo no)"
    status_line "RUN_ANY_IN_BACKGROUND" "${bg:-?}"
    if [ "$MODE" = "root" ]; then
        status_line "oom_score_adj (this shell)" "$(cat /proc/$$/oom_score_adj 2>/dev/null)   (negative = skipped by lmkd)"
        status_line "lmkd guard" "$(guard_running && echo running || echo stopped)"
    fi
    if [ "$mon" = "false" ] && [ "${wl:-0}" -ge 1 ]; then
        ok "Protection ACTIVE."
    else
        warn "Protection INACTIVE or partial."
    fi
}

# ---------------------------------------------------------------------------
COMMAND=""
while [ $# -gt 0 ]; do
    case "$1" in
        setup | on | off | status | help) COMMAND="$1" ;;
        *) std_opt "$@" || die "Unknown argument: $1 (try --help)"; shift "$STD_SHIFT"; continue ;;
    esac
    shift
done

mkdir -p "$STATE_DIR"
log_init
case "$COMMAND" in
    setup) do_setup ;;
    on) do_on ;;
    off) do_off ;;
    status) do_status ;;
    help) usage ;;
    *) usage >&2; exit 2 ;;
esac
